413	/** 一天的有效/异常/未知覆盖秒数后缀;采用间隔限制时附上过长间隔造成的未知秒数。 */
414	function coverageSuffix(
415	  stats: Pick<DayStats, 'valid' | 'anomaly' | 'unknown' | 'gapUnknown'>,
416	  limited: boolean,
417	): string {
418	  const base = `valid=${stats.valid}s anomaly=${stats.anomaly}s unknown=${stats.unknown}s`;
419	  return limited ? `${base} gap=${stats.gapUnknown}s` : base;
420	}
421	
422	/**
423	 * 消耗比较短语:无有效覆盖时明确表示消耗无法计算(不显示 0、也不触发或恢复);
424	 * 有效(含零增长)时给出固定三位小数消耗及与阈值的比较。
425	 */
426	function consumptionCompare(stats: DayStats, threshold: bigint): string {
427	  if (stats.valid === 0) return 'consumption=n/a (no valid coverage)';
428	  const exceeded = stats.consumption > threshold;
429	  return (
430	    `consumption=${formatKwh(stats.consumption)} kWh ` +
431	    `${exceeded ? '>' : '<='} threshold=${formatKwh(threshold)} kWh`
432	  );
433	}
