445	/** 规则时区的墙钟格式化器;存储载入时已校验,此处不会失败。 */
446	function ruleFormat(rule: AlertRule): Intl.DateTimeFormat {
447	  const fmt = loadTimezone(rule.tz);
448	  if (fmt === null) {
449	    throw new StoreError(`rule '${rule.id}' has invalid timezone '${rule.tz}' in storage`);
450	  }
451	  return fmt;
452	}
