454	/**
455	 * 规则在一个当地日期上实际参与判定的 UTC 时段:全天模式为该日期的全部
456	 * 实际时段;非运行模式为这些时段按规则固定的每周运行时间表分类后的非
457	 * 运行部分(分类沿用 group schedule-report 的口径:按实际时刻的当地日期
458	 * 与墙钟,回拨重复小时各自分类,跳过时段不虚构)。同一日期的不连续时段
459	 * 分别分类后合并在同一日期下参与一次判定。
460	 */
461	function ruleDayPeriods(rule: AlertRule, fmt: Intl.DateTimeFormat, day: LocalDay): LocalDayPeriod[] {
462	  if (rule.schedule === undefined) return day.periods;
463	  const out: LocalDayPeriod[] = [];
464	  for (const p of day.periods) {
465	    out.push(...classifyPeriods(fmt, p.start, p.end, rule.schedule).nonRunning);
466	  }
467	  return out;
468	}
469	
470	/**
471	 * 计算规则在给定 UTC 时段集合上的统计(这些时段属于同一当地日期)。
472	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径;
473	 * 日界线、时间表边界与成员切换都不重置各设备原读数区间的分摊起点。
474	 * maxInterval 为规则固定的采样间隔限制(省略为无上限)。
475	 */
476	function computeRuleDay(env: RuleEnv, periods: LocalDayPeriod[], maxInterval?: number): DayStats {
477	  let valid = 0;
478	  let anomaly = 0;
479	  let unknown = 0;
480	  let gapUnknown = 0;
481	  const gaps: GapDetail[] = [];
482	  let consumption = 0n;
483	  for (const p of periods) {
484	    if (env.kind === 'device') {
485	      const s = computeDay(env.series, p.start, p.end, maxInterval);
486	      valid += s.valid;
487	      anomaly += s.anomaly;
488	      unknown += s.unknown;
489	      gapUnknown += s.gapUnknown;
490	      mergeGaps(gaps, s.gaps);
491	      consumption += s.consumption;
492	    } else {
493	      const s = computeGroupSegment(env.group.versions, env.byDevice, p.start, p.end, maxInterval);
494	      valid += s.valid;
495	      anomaly += s.anomaly;
496	      unknown += s.unknown;
497	      gapUnknown += s.gapUnknown;
498	      mergeGaps(gaps, s.gaps);
499	      consumption += s.consumption;
500	    }
501	  }
502	  return { valid, anomaly, unknown, gapUnknown, gaps, consumption };
503	}
