629	/** 列出全部规则(含目标类型、时区、采样间隔限制、模式及固定时间表)。只读。返回进程退出码。 */
630	export function cmdRuleList(): number {
631	  let state: AlertState;
632	  try {
633	    state = loadAlertState(alertFilePath());
634	  } catch (e) {
635	    if (e instanceof StoreError) {
636	      err(e.message);
637	      return 1;
638	    }
639	    throw e;
640	  }
641	  if (state.rules.length === 0) {
642	    console.log('no rules defined');
643	    return 0;
644	  }
645	  const rules = [...state.rules].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
646	  for (const r of rules) {
647	    const open = state.alerts.filter((a) => a.ruleId === r.id && a.status === 'triggered').length;
648	    console.log(
649	      `rule ${r.id}  ${targetLabel(r)}  threshold=${formatKwh(r.thresholdMilli)} kWh  ` +
650	        `tz=${r.tz}  max-interval=${maxIntervalText(r.maxInterval)}  ${modeText(r)}  open alerts=${open}`,
651	    );
652	  }
653	  return 0;
654	}
655	
656	/**
657	 * 评估规则在连续完整当地日期范围 [from, to)(规则时区的 YYYY-MM-DD,起日含、
658	 * 止日不含)上的超限情况。每个日期统计归属该日期的全部实际 UTC 时段,一次
659	 * 评估只作一次判定;整日被跳过的日期标明跳过,不判定、不创建也不恢复告警。
660	 * 非运行模式的规则每天只取这些时段中的非运行部分参与判定(运行时段的异常
661	 * 或未知不阻止判定);没有非运行秒数的日期标明原因,同样不判定、不创建也
662	 * 不恢复。全部日期计算并应用到内存状态后一次性原子写入,不部分提交;中途
663	 * 任一存储或数据错误都在写入前抛出,操作前状态保留。返回进程退出码。
664	 */
665	export function cmdEvaluate(opts: { ruleId: string; from: string; to: string }): number {
666	  const statePath = alertFilePath();
667	  let state: AlertState;
668	  let rule: AlertRule;
669	  let env: RuleEnv;
670	  let fmt: Intl.DateTimeFormat;
671	  try {
672	    state = loadAlertState(statePath);
673	    const found = state.rules.find((r) => r.id === opts.ruleId);
674	    if (!found) {
675	      err(`unknown rule '${opts.ruleId}'`);
676	      return 1;
677	    }
678	    rule = found;
679	    env = prepareEnv(rule);
680	    fmt = ruleFormat(rule);
681	  } catch (e) {
682	    if (e instanceof StoreError) {
683	      err(e.message);
684	      return 1;
685	    }
686	    throw e;
687	  }
688	
689	  // 既有告警标识集合:新标识不得与旧告警冲突(正常情况下编号单调递增不可能
690	  // 碰撞,这里再显式防御,碰撞则整体中止且不写入)。
691	  const alertIds = new Set(state.alerts.map((a) => a.id));
692	
693	  const threshold = rule.thresholdMilli;
694	  const limited = rule.maxInterval !== undefined;
695	  const lines: string[] = [];
696	  for (const { label, day } of localDateRange(fmt, opts.from, opts.to)) {
697	    if (day === null) {
698	      // 整日被跳过(无实际时段):不判定、不触发也不恢复。
699	      lines.push(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})  no alert action`);
700	      continue;
701	    }
702	    // 全天模式为当天全部实际时段;非运行模式只取其中的非运行部分。
703	    const periods = ruleDayPeriods(rule, fmt, day);
704	    let periodSeconds = 0;
705	    for (const p of periods) periodSeconds += p.end - p.start;
706	    if (periodSeconds === 0) {
707	      // 非运行模式且当天没有非运行秒数:说明原因,不判定、不触发也不恢复。
708	      lines.push(
709	        `  ${label}  NO NON-RUNNING COVERAGE (running windows cover the whole local date)  no alert action`,
710	      );
711	      continue;
712	    }
713	    const stats = computeRuleDay(env, periods, rule.maxInterval);
714	    const coverage = coverageSuffix(stats, limited);
715	    if (stats.unknown > 0 || stats.anomaly > 0) {
716	      // 有未知或下降覆盖:不可判定,不触发也不恢复。无有效覆盖时明确显示
717	      // 消耗无法计算(不显示 0);仍有部分有效覆盖时只给覆盖与原因,不与阈值比较。
718	      const head =
719	        stats.valid === 0
720	          ? `  ${label}  undecidable  ${consumptionCompare(stats, threshold)}  (${coverage})  no alert action`
721	          : `  ${label}  undecidable (${coverage})  no alert action`;
722	      lines.push(head);
723	      lines.push(...periodLines(periods));
724	      lines.push(...gapLines(stats, rule));
725	      continue;
726	    }
727	    const exceeded = stats.consumption > threshold;
728	    const cmp = consumptionCompare(stats, threshold);
729	    const open = state.alerts.find(
730	      (a) => a.ruleId === rule.id && a.date === label && a.status === 'triggered',
731	    );
732	    if (exceeded) {
733	      if (open) {
734	        // 重复超限:保留原标识,不新增事件。
735	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${open.id} remains triggered  ${coverage}`);
736	      } else {
737	        const id = `alert-${state.nextAlertNum++}`;
738	        if (alertIds.has(id)) {
739	          err(`storage error: generated alert id '${id}' already exists; nothing was written`);
740	          return 1;
741	        }
742	        alertIds.add(id);
743	        state.alerts.push({
744	          id,
745	          ruleId: rule.id,
746	          date: label,
747	          status: 'triggered',
748	          acknowledged: false,
749	          events: [
750	            { seq: state.nextEventSeq++, type: 'triggered', consumptionMilli: stats.consumption.toString() },
751	          ],
752	        });
753	        lines.push(`  ${label}  ${cmp}  EXCEEDED  alert ${id} triggered (unacknowledged)  ${coverage}`);
754	      }
755	    } else {
756	      if (open) {
757	        open.status = 'recovered';
758	        open.events.push({
759	          seq: state.nextEventSeq++,
760	          type: 'recovered',
761	          consumptionMilli: stats.consumption.toString(),
762	        });
763	        lines.push(`  ${label}  ${cmp}  NORMAL  alert ${open.id} recovered  ${coverage}`);
764	      } else {
765	        lines.push(`  ${label}  ${cmp}  NORMAL  no alert  ${coverage}`);
766	      }
767	    }
768	    lines.push(...periodLines(periods));
769	  }
770	
771	  try {
772	    saveAlertState(statePath, state);
773	  } catch (e) {
774	    if (e instanceof StoreError) {
775	      err(e.message);
776	      return 1;
777	    }
778	    throw e;
779	  }
780	
781	  console.log(
782	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
783	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}  ${modeText(rule)}`,
784	  );
785	  for (const line of lines) console.log(line);
786	  return 0;
787	}
788	
789	/**
790	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
791	 * 给定日期范围时按规则时区的当地日期逐日展示当前计算的消耗或不可判定原因、
792	 * 实际 UTC 时段与各次告警;省略范围时展示有告警记录的全部日期。触发/恢复
793	 * 事件中的消耗为评估当时记录,不随后续数据变化改写。返回进程退出码。
794	 */
795	export function cmdAlerts(opts: { ruleId: string; from?: string; to?: string }): number {
796	  let state: AlertState;
797	  let rule: AlertRule;
798	  let env: RuleEnv;
799	  let fmt: Intl.DateTimeFormat;
800	  try {
801	    state = loadAlertState(alertFilePath());
802	    const found = state.rules.find((r) => r.id === opts.ruleId);
803	    if (!found) {
804	      err(`unknown rule '${opts.ruleId}'`);
805	      return 1;
806	    }
807	    rule = found;
808	    env = prepareEnv(rule);
809	    fmt = ruleFormat(rule);
810	  } catch (e) {
811	    if (e instanceof StoreError) {
812	      err(e.message);
813	      return 1;
814	    }
815	    throw e;
816	  }
817	
818	  // 待展示的当地日期(升序):给定范围时为范围内全部日期;省略范围时为有告警
819	  // 记录的全部日期。
820	  let labels: string[];
821	  if (opts.from !== undefined && opts.to !== undefined) {
822	    labels = localDateRange(fmt, opts.from, opts.to).map((e) => e.label);
823	  } else {
824	    labels = [
825	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
826	    ].sort();
827	  }
828	
829	  console.log(
830	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh  ` +
831	      `tz=${rule.tz}  max-interval=${maxIntervalText(rule.maxInterval)}  ${modeText(rule)}`,
832	  );
833	  if (labels.length === 0) {
834	    console.log(`  no alerts recorded for rule '${rule.id}'`);
835	    return 0;
836	  }
837	
838	  // 各当地日期的实际 UTC 时段;整日被跳过的日期为 null。日历日期逐日递增,
839	  // 末日后延一天作为切分终点。
840	  const last = parseUtcDate(labels[labels.length - 1]) as number;
841	  const endLabel = formatIsoUtc(last + DAY_SECONDS).slice(0, 10);
842	  const byLabel = new Map<string, LocalDay | null>();
843	  for (const e of localDateRange(fmt, labels[0], endLabel)) byLabel.set(e.label, e.day);
844	
845	  const threshold = rule.thresholdMilli;
846	  const limited = rule.maxInterval !== undefined;
847	  for (const label of labels) {
848	    const day = byLabel.get(label) ?? null;
849	    if (day === null) {
850	      console.log(`  ${label}  SKIPPED (no such local date in timezone ${rule.tz})`);
851	    } else {
852	      // 全天模式为当天全部实际时段;非运行模式只取其中的非运行部分。
853	      const periods = ruleDayPeriods(rule, fmt, day);
854	      let periodSeconds = 0;
855	      for (const p of periods) periodSeconds += p.end - p.start;
856	      if (periodSeconds === 0) {
857	        console.log(`  ${label}  NO NON-RUNNING COVERAGE (running windows cover the whole local date)`);
858	      } else {
859	        const stats = computeRuleDay(env, periods, rule.maxInterval);
860	        if (stats.unknown > 0 || stats.anomaly > 0) {
861	          // 不可判定;无有效覆盖时明确显示消耗无法计算,不显示 0 或与阈值比较。
862	          const head =
863	            stats.valid === 0
864	              ? `  ${label}  undecidable  ${consumptionCompare(stats, threshold)}  (${coverageSuffix(stats, limited)})`
865	              : `  ${label}  undecidable (${coverageSuffix(stats, limited)})`;
866	          console.log(head);
867	        } else {
868	          const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
869	          console.log(
870	            `  ${label}  consumption=${formatKwh(stats.consumption)} kWh ` +
871	              `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)  ${coverageSuffix(stats, limited)}`,
872	          );
873	        }
874	        for (const line of periodLines(periods)) console.log(line);
875	        for (const line of gapLines(stats, rule)) console.log(line);
876	      }
877	    }
878	    const alerts = state.alerts
879	      .filter((a) => a.ruleId === rule.id && a.date === label)
880	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
881	    if (alerts.length === 0) {
882	      console.log('    no alerts');
883	      continue;
884	    }
885	    for (const a of alerts) {
886	      console.log(
887	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
888	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
889	      );
890	      const events = a.events
891	        .map((e) => {
892	          const consumption =
893	            e.consumptionMilli !== undefined
894	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
895	              : '';
896	          return `#${e.seq} ${e.type}${consumption}`;
897	        })
898	        .join(', ');
899	      console.log(`      events: ${events}`);
900	    }
901	  }
902	  return 0;
903	}
904	
905	/**
906	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
907	 * 确认不改变超限或恢复状态。返回进程退出码。
908	 */
909	export function cmdAck(alertId: string): number {
910	  const statePath = alertFilePath();
911	  let state: AlertState;
912	  try {
913	    state = loadAlertState(statePath);
914	  } catch (e) {
915	    if (e instanceof StoreError) {
916	      err(e.message);
917	      return 1;
918	    }
919	    throw e;
920	  }
921	  const alert = state.alerts.find((a) => a.id === alertId);
922	  if (!alert) {
923	    err(`unknown alert '${alertId}'`);
924	    return 1;
925	  }
926	  if (alert.acknowledged) {
927	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
928	    return 0;
929	  }
930	  alert.acknowledged = true;
931	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
932	  try {
933	    saveAlertState(statePath, state);
934	  } catch (e) {
935	    if (e instanceof StoreError) {
936	      err(e.message);
937	      return 1;
938	    }
939	    throw e;
940	  }
941	  const rule = state.rules.find((r) => r.id === alert.ruleId);
942	  const target = rule ? ` ${targetLabel(rule)}` : '';
943	  console.log(
944	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
945	  );
946	  return 0;
947	}
