178	export interface WallSegment {
179	  /** 段起点(含),epoch 秒。 */
180	  start: number;
181	  /** 段终点(不含),epoch 秒。 */
182	  end: number;
183	  /** 段内当地日期标签,YYYY-MM-DD。 */
184	  label: string;
185	  /** 段内恒定偏移(墙钟 - UTC),秒。 */
