694	/**
695	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
696	 * 各恰好一个。出错返回错误消息字符串。
697	 */
698	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
699	  const segments: string[][] = [[]];
700	  for (const tok of rest) {
701	    if (tok === '--item') segments.push([]);
702	    else segments[segments.length - 1].push(tok);
703	  }
704	  const headFlags = parseFlags(segments[0], ['--request']);
705	  if (typeof headFlags === 'string') return headFlags;
706	  const requestRaw = oneFlag(headFlags, '--request');
707	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
708	  const requestId = requestRaw.trim();
709	  if (requestId === '') return '请求标识不能为空';
710	  const itemSegs = segments.slice(1);
711	  if (itemSegs.length === 0) {
712	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
713	  }
714	  const items: CorrectionItem[] = [];
715	  for (const seg of itemSegs) {
716	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
717	    if (typeof flags === 'string') return flags;
718	    const deviceRaw = oneFlag(flags, '--device');
719	    const atRaw = oneFlag(flags, '--at');
720	    const expectRaw = oneFlag(flags, '--expect');
721	    const setRaw = oneFlag(flags, '--set');
722	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
723	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
724	    }
725	    const device = deviceRaw.trim();
726	    if (device === '') return "'--device' 的值不能为空";
727	    const ts = parseIso8601(atRaw.trim());
728	    if (ts === null) {
729	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
730	    }
731	    const expectedMilli = parseKwh(expectRaw.trim());
732	    if (expectedMilli === null) {
733	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
734	    }
735	    const replacementMilli = parseKwh(setRaw.trim());
736	    if (replacementMilli === null) {
737	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
738	    }
739	    items.push({ device, ts, expectedMilli, replacementMilli });
740	  }
741	  return { requestId, items };
742	}
