298	    // 30 分钟密采样尾部(自 03:00 起每 1800s 一个,恰等于限制 => 可信,至次日00:00)。
299	    const dense = [];
300	    for (let total = 3 * 60; total <= 24 * 60; total += 30) {
301	      const h = Math.floor(total / 60);
302	      const mi = total % 60;
303	      if (h === 24) {
304	        dense.push(['x', '2026-01-14T00:00:00Z'], ['y', '2026-01-14T00:00:00Z']);
305	      } else {
306	        const ts = `2026-01-13T${String(h).padStart(2, '0')}:${String(mi).padStart(2, '0')}:00Z`;
307	        dense.push(['x', ts], ['y', ts]);
308	      }
309	    }
310	    const rows = ['device,time,reading',
311	      // 长原始区间 [前日23:00,01:00)(7200s>1800),两成员共有,覆盖 [00,01)。
312	      'x,2026-01-12T23:00:00Z,0.000',
313	      'x,2026-01-13T01:00:00Z,0.000',
314	      // x 的 [01:00,02:30) 长 5400s>1800(与 y 的下降重叠:验证按原区间判断与并集)。
315	      'x,2026-01-13T02:30:00Z,0.000',
316	      // y:[01:00,02:00) 下降(2.000->1.000);下降后继续。
317	      'y,2026-01-12T23:00:00Z,0.000',
318	      'y,2026-01-13T01:00:00Z,2.000',
319	      'y,2026-01-13T02:00:00Z,1.000',
320	      'y,2026-01-13T02:30:00Z,1.000'];
321	    for (const [dev, ts] of dense) rows.push(`${dev},${ts},1.500`);
322	    write(join(dir, 'r.csv'), rows.join('\n') + '\n');
323	    write(join(dir, 'empty.txt'), '# non-running all day\n');
324	    let r = run(dir, ['import', 'r.csv']);
325	    check(S, r.code === 0, `import rc=${r.code} ${r.err}`);
326	    r = run(dir, ['group', 'configure', '--id', 'g2', '--at', '2026-01-01T00:00:00Z', '--device', 'x', '--device', 'y']);
327	    check(S, r.code === 0, `group rc=${r.code} ${r.err}`);
