535	    check(S, readJson(dir, 'readings.json').readings.find(
536	      (x) => x.device === 'm' && x.ts === Date.parse('2026-01-06T00:00:00Z') / 1000).milli === '2000',
537	      'replay of undone correction must not re-apply');
538	
539	    // 撤销是数据操作,不自动改检测状态:仍 recovered。
540	    state = readJson(dir, 'alerts.json');
541	    check(S, state.alerts[0].status === 'recovered', 'undo must not auto-change detection status');
542	
543	    // 8) 显式重评再次超限 => 创建“新的未确认”告警 alert-2;旧记录与确认保留。
544	    r = run(dir, ['evaluate', '--rule', 'nr', '--from', '2026-01-05', '--to', '2026-01-06']);
