611	    state = readJson(dir, 'alerts.json');
612	    check(S, state.nextAlertNum === 4 && state.nextEventSeq === 4, 'counters continue without collision');
613	  } finally {
614	    // 确保故障标志一定解除,再清理临时目录。
615	    try { execFileSync('chflags', ['nouchg', join(dir, 'alerts.json')]); } catch { /* may not exist */ }
616	    rmSync(dir, { recursive: true, force: true });
617	  }
618	}
