canonicalizeExceptions:

```ts
export function canonicalizeExceptions(exceptions: DateException[]): DateException[] {
  const byDate = new Map<string, DateException>();
  for (const e of exceptions) {
    const cur = byDate.get(e.date);
    if (!cur) { byDate.set(e.date, { date: e.date, shutdown: e.shutdown, windows: [...e.windows] }); }
    else { cur.shutdown = cur.shutdown || e.shutdown; cur.windows.push(...e.windows); }
  }
  const out: DateException[] = [];
  for (const e of byDate.values()) {
    if (e.shutdown) { out.push({ date: e.date, shutdown: true, windows: [] }); continue; }
    const covered = new Uint8Array(1440);
    for (const w of e.windows) for (let m = w.startMin; m < w.endMin; m++) covered[m] = 1;
    const wins: ExceptionWindow[] = [];
    let m = 0;
    while (m < 1440) {
      if (covered[m] === 0) { m++; continue; }
      const s = m;
      while (m < 1440 && covered[m] === 1) m++;
      wins.push({ startMin: s, endMin: m });
    }
    out.push({ date: e.date, shutdown: false, windows: wins });
  }
  out.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
  return out;
}
```

