```ts
function scheduleEquals(a?: Schedule, b?: Schedule): boolean {
  if (a === undefined || b === undefined) return a === b;
  const ca = canonicalizeSchedule(a);
  const cb = canonicalizeSchedule(b);
  if (ca.windows.length !== cb.windows.length) return false;
  for (let i = 0; i < ca.windows.length; i++) {
    const w = ca.windows[i]; const v = cb.windows[i];
    if (w.startDow !== v.startDow || w.startMin !== v.startMin || w.endMin !== v.endMin) return false;
  }
  if (ca.exceptions.length !== cb.exceptions.length) return false;
  for (let i = 0; i < ca.exceptions.length; i++) {
    const x = ca.exceptions[i]; const y = cb.exceptions[i];
    if (x.date !== y.date || x.shutdown !== y.shutdown || x.windows.length !== y.windows.length) return false;
    for (let j = 0; j < x.windows.length; j++) {
      if (x.windows[j].startMin !== y.windows[j].startMin || x.windows[j].endMin !== y.windows[j].endMin) return false;
    }
  }
  return true;
}
```

