    check(S, r.code === 0 && /consumption=2\.000 kWh/.test(r.out.replace(/\n/g, ' ')) || /2\.000 kWh/.test(r.out),
      `class consumption sum must match group daily total 2.000:\n${r.out}`);

    // 例外窗口覆盖全天:没有非运行秒数,说明原因,不判定不告警。
    write(join(dir, 'cov.txt'), '2026-01-05 00:00 24:00\n');
